#include<cstdio>
int n,m,a[500005],b[300005],ans[300005];//a[i]:第i个点数,b[i]:点数i的位置
int main(){
    freopen("card.in","r",stdin);
    freopen("card.out","w",stdout);
    scanf("%d%d",&n,&m);
    for(int i=1;i<=n;i++){
        scanf("%d",&a[i]);
    }
    for(int i=1;i<=n;i++){
        for(int j=i;j<=n;j++){
            if(b[a[j]]){
                for(int k=b[a[j]];k<j;k++){
                    b[a[k]]=0;
                }
            }
            b[a[j]]=j;
        }
        for(int j=1;j<=m;j++){
            if(b[j])ans[j]++;
        }
        for(int j=1;j<=m;j++){
            b[j]=0;
        }
    }
    for(int i=1;i<=m;i++){
        printf("%d ",ans[i]);
    }
    return 0;
}

